mapper.delete:
DELETE FROM ai_chat_memory
WHERE conversation_id = #{conversationId}
  AND (user_id = #{userId} OR conversation_id LIKE CONCAT('%:', #{userId}, ':%'))

mapper.select:
SELECT id, conversation_id, user_id, agent_id, run_id, message_type, content, created_at
FROM ai_chat_memory
WHERE conversation_id = #{conversationId}

    AND id < #{beforeId}

ORDER BY id DESC
LIMIT #{limit}
